	private static void writeExport(RepositoryConnection connection, RDFWriterFactory factory, RDFFormat format,
			Compression compression, OutputStream output, int timeoutSeconds) throws Exception {
		switch (compression) {
		case NONE:
			connection.export(withTimeout(factory.getWriter(output), timeoutSeconds));
			break;
		case GZIP: {
			AbandonableGzipOutputStream gzip = new AbandonableGzipOutputStream(output);
			boolean exported = false;
			try {
				connection.export(withTimeout(factory.getWriter(gzip), timeoutSeconds));
				exported = true;
			} finally {
				if (!exported) {
					gzip.abandon();
				}
			}
			gzip.close();
			break;
		}
		case ZIP: {
			AbandonableZipOutputStream zip = new AbandonableZipOutputStream(output);
			boolean exported = false;
			try {
				zip.putNextEntry(new ZipEntry("export." + format.getDefaultFileExtension()));
				connection.export(withTimeout(factory.getWriter(zip), timeoutSeconds));
				zip.closeEntry();
				exported = true;
			} finally {
				if (!exported) {
					zip.abandon();
				}
			}
			zip.close();
			break;
		}
		default:
			throw new IllegalStateException("Unsupported export compression: " + compression);
		}
	}

